?><!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order #<?=e($id)?></title><link rel="stylesheet" href="../assets/style.css"></head><body class="admin-body"><aside class="admin-sidebar"><h2>GadgetMart</h2><nav><a href="index.php">ড্যাশবোর্ড</a><a href="products.php">প্রোডাক্ট</a><a class="active" href="orders.php">অর্ডার</a><a href="settings.php">সেটিংস</a><a href="logout.php">লগআউট</a></nav></aside><main class="admin-main"><div class="topbar"><h1>অর্ডার #<?=e($id)?></h1><a class="btn btn-secondary" href="orders.php">ফিরে যান</a></div><section class="panel"><p><b>কাস্টমার:</b> <?=e($order['customer_name'])?></p><p><b>ফোন:</b> <?=e($order['phone'])?></p><p><b>ইমেইল:</b> <?=e($order['email']??'')?></p><p><b>ঠিকানা:</b> <?=e($order['address'])?></p><p><b>স্ট্যাটাস:</b> <?=e($order['status'])?></p><p><b>পেমেন্ট:</b> <?=e($order['payment_method']??'cod')?> / <?=e($order['payment_status']??'unpaid')?></p><div class="table-wrap"><table><tr><th>প্রোডাক্ট</th><th>পরিমাণ</th><th>ইউনিট মূল্য</th><th>মোট</th></tr><?php foreach($items as $item):?><tr><td><?=e($item['product_name'])?></td><td><?=e($item['quantity'])?></td><td>৳<?=e(number_format((float)$item['unit_price'],2))?></td><td>৳<?=e(number_format((float)$item['unit_price']*$item['quantity'],2))?></td></tr><?php endforeach;?></table></div><h3>মোট: ৳<?=e(number_format((float)$order['total'],2))?></h3></section></main></body></html>
